input.command:
cat > tests/checkout_test.sh <<'EOF'
#!/bin/bash
fail=0
f=$(mktemp)
out=$(LOANS=$f bash bin/checkout DMM-3 test 2026-11-01)
[ "$out" = "checked out DMM-3 to test" ] || { echo "checkout output"; fail=1; }
[ "$(wc -l < "$f")" -eq 1 ] || { echo "checkout appends"; fail=1; }
rm -f "$f"

# LAB-7: 校正期限切れ / 校正記録なしは貸し出さない（記録も書かない）
g=$(mktemp)
if LOANS=$g bash bin/checkout OSC-2 test 2026-11-01 >/dev/null 2>&1; then echo "expired must fail"; fail=1; fi
[ ! -s "$g" ] || { echo "expired must not be recorded"; fail=1; }
if LOANS=$g bash bin/checkout FG-5 test 2026-11-01 >/dev/null 2>&1; then echo "unrecorded must fail"; fail=1; fi
[ ! -s "$g" ] || { echo "unrecorded must not be recorded"; fail=1; }
# 期限日当日は貸出可
LOANS=$g bash bin/checkout OSC-2 test 2026-10-31 >/dev/null 2>&1 || { echo "due date must be allowed"; fail=1; }
[ "$(wc -l < "$g")" -eq 1 ] || { echo "due date recorded"; fail=1; }
rm -f "$g"
exit $fail
EOF
bash tests/checkout_test.sh

toolUseResult.originalFile:
#!/bin/bash
# calib_ok <device> <today YYYY-MM-DD>: succeeds while the device's calibration is valid
# (the due date itself is still valid). Records: $CALIB (default data/calibration.tsv).
calib_ok() {
  local file=${CALIB:-data/calibration.tsv} due
  due=$(awk -F'\t' -v d="$1" '$1 == d { print $2 }' "$file")
  [ -z "$due" ] && return 0
  [[ ! "$due" < "$2" ]]
}
